<template>
  <aside class="voice-catalog">
    <header class="section-heading"><div><span class="overline">VOICE LIBRARY</span><h2>音色库 <small>{{ voices.length }}</small></h2></div><button class="icon-btn" title="刷新音色" aria-label="刷新音色" @click="$emit('refresh')"><RefreshCw :size="16" /></button></header>
    <div class="catalog-filters">
      <div class="search-field"><Search :size="15" /><input :value="search" aria-label="搜索音色" placeholder="搜索音色或语言" @input="$emit('update:search', ($event.target as HTMLInputElement).value)" /></div>
      <div class="filter-row"><select :value="language" aria-label="筛选语言" @change="$emit('update:language', ($event.target as HTMLSelectElement).value)"><option value="">全部语言</option><option v-for="lang in languages" :key="lang" :value="lang">{{ lang }}</option></select><button class="icon-btn" :class="{ selected: favoritesOnly }" title="只看收藏" aria-label="只看收藏" :aria-pressed="favoritesOnly" @click="$emit('update:favoritesOnly', !favoritesOnly)"><Star :size="16" :fill="favoritesOnly ? 'currentColor' : 'none'" /></button></div>
    </div>
    <div class="voice-list" role="group" aria-label="可用音色">
      <button class="auto-voice" :class="{ chosen: !draft.voiceURI }" @click="$emit('select')"><AudioLines :size="19" /><span><strong>自动选择</strong><small>{{ draft.lang || '系统默认语言' }}</small></span><Check v-if="!draft.voiceURI" :size="16" /></button>
      <div v-for="voice in filteredVoices" :key="voice.voiceURI" class="voice-option" :class="{ chosen: draft.voiceURI === voice.voiceURI }">
        <button class="voice-choice" :aria-pressed="draft.voiceURI === voice.voiceURI" @click="$emit('select', voice)"><span class="voice-monogram">{{ voice.lang.slice(0, 2).toUpperCase() }}</span><span class="voice-copy"><strong>{{ voice.name }}</strong><small>{{ voice.lang }}<span class="separator">·</span>{{ voice.localService ? '本地' : '网络' }}<span v-if="voice.default" class="default-badge">默认</span></small></span><Check v-if="draft.voiceURI === voice.voiceURI" :size="14" /></button>
        <button class="icon-btn star-btn" :class="{ selected: draft.favoriteVoiceURIs.includes(voice.voiceURI) }" :aria-label="`${draft.favoriteVoiceURIs.includes(voice.voiceURI) ? '取消收藏' : '收藏'} ${voice.name}`" :title="draft.favoriteVoiceURIs.includes(voice.voiceURI) ? '取消收藏' : '收藏音色'" @click="$emit('favorite', voice.voiceURI)"><Star :size="14" :fill="draft.favoriteVoiceURIs.includes(voice.voiceURI) ? 'currentColor' : 'none'" /></button>
      </div>
      <div v-if="!supported" class="catalog-empty"><VolumeX :size="26" /><strong>浏览器不支持语音合成</strong></div>
      <div v-else-if="!voices.length" class="catalog-empty"><AudioLines :size="26" /><strong>尚未发现可用音色</strong><button class="text-btn" @click="$emit('refresh')">重新检测</button></div>
      <p v-else-if="!filteredVoices.length" class="empty-filter">没有匹配的音色</p>
    </div>
    <footer class="catalog-footer"><span class="device-dot"></span>浏览器语音引擎 <span>{{ supported ? '已连接' : '不可用' }}</span></footer>
  </aside>
</template>
<script setup lang="ts">
import { AudioLines, Check, RefreshCw, Search, Star, VolumeX } from '@lucide/vue';
import type { VoiceDescriptor } from '../../voice/browserSpeech';
import type { VoiceConfig } from '../../voice/voiceConfig';
defineProps<{ voices: VoiceDescriptor[]; filteredVoices: VoiceDescriptor[]; languages: string[]; search: string; language: string; favoritesOnly: boolean; draft: VoiceConfig; supported: boolean }>();
defineEmits<{
  refresh: []; select: [voice?: VoiceDescriptor]; favorite: [uri: string];
  'update:search': [value: string]; 'update:language': [value: string]; 'update:favoritesOnly': [value: boolean];
}>();
</script>
